// The Funniest AI Out-of-Office Reply: writes one original out-of-office
// reply, written as an AI, to $MAKEFUN_OUTPUT_DIR/entry.txt (default /output).
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const LINE =
  "I'm out of the office until Monday — this reply was auto-generated by an AI, so technically I'm not ignoring you, a robot is.";

const outDir = process.env.MAKEFUN_OUTPUT_DIR ?? "/output";

const chars = [...LINE].length;
if (LINE.trim().length === 0 || chars < 1 || chars > 200) {
  console.error(`entry line must be 1-200 characters, got ${chars}`);
  process.exit(1);
}
if (/[\r\n]/.test(LINE)) {
  console.error("entry line must not contain a line break");
  process.exit(1);
}
const bytes = Buffer.byteLength(LINE, "utf8");
if (bytes > 800) {
  console.error(`entry line is ${bytes} UTF-8 bytes, over the 800-byte cap`);
  process.exit(1);
}

mkdirSync(outDir, { recursive: true });
const target = join(outDir, "entry.txt");
writeFileSync(target, LINE, "utf8");
// Read back what landed on disk and refuse to report success unless the
// stored bytes match the validated line exactly, so a partial or altered
// write can never pass as a clean entry.
const stored = readFileSync(target, "utf8");
if (stored !== LINE) {
  console.error(`verification failed: ${target} does not match the entry line`);
  process.exit(1);
}
console.log(`wrote ${chars} characters to ${target}`);
